static bool parse_seq(const vector<string>& t,size_t& p,vector<Node>& out,int depth,bool closing) { if(depth>8)return false; while(p<t.size()){if(t[p]=="}"){if(!closing)return false;p++;return true;} if(t[p]=="{"||t[p]==";")return false; Node n;n.name=t[p++];while(p<t.size()&&t[p]!=";"&&t[p]!="{"&&t[p]!="}"){n.args.push_back(t[p++]);if(n.args.size()>32)return false;}if(p==t.size()||t[p]=="}")return false; if(t[p++]=="{"){n.block=true;if(!parse_seq(t,p,n.children,depth+1,true))return false;}out.push_back(move(n));}return !closing; }
