static const Node* child(const vector<Node>& n,const string& name) {for(auto& x:n)if(x.name==name)return &x;return nullptr;}
static string val(const vector<Node>& n,const string& k,string d="") {auto p=child(n,k);return p&&!p->args.empty()?p->args[0]:d;}
struct Location{string path,root,alias,index="index.html",rtype,dest,proxy;bool exact=false;};
struct Server{vector<pair<int,bool>> listens;vector<string> names;vector<Location> loc;string root="html",cert,key; SSL_CTX* ctx=nullptr;};
