int main(int argc,char**argv){if(argc!=3||(string(argv[1])!="--config"&&string(argv[1])!="--check-config")){cerr<<"usage: server --config PATH\n";return 1;}string file=argv[2];Config c;auto slash=file.find_last_of('/');c.base=slash==string::npos?".":file.substr(0,slash);Settings s;if(!loadfile(c,file,c.nodes,0)||!build(c,s)){cerr<<file<<":1: invalid configuration\n";return 1;}if(!setup_tls(s)){cerr<<file<<":1: invalid TLS material\n";return 1;}if(string(argv[1])=="--check-config")return 0;vector<pair<int,int>> listeners;set<int> ports;for(auto& v:s.servers)for(auto p:v.listens)if(ports.insert(p.first).second){int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);int one=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(p.first);if(bind(fd,(sockaddr*)&a,sizeof(a))||listen(fd,1024)){perror("listen");return 1;}listeners.push_back({fd,p.first});}signal(SIGTERM,onterm);signal(SIGINT,onterm);signal(SIGCHLD,onchild);signal(SIGPIPE,SIG_IGN);vector<pid_t> kids;auto spawn=[&](){pid_t p=fork();if(p==0)worker(s,listeners);if(p>0)kids.push_back(p);};for(int i=0;i<s.workers;i++)spawn();while(!stopflag){pause();if(chldflag){chldflag=0;int st;pid_t p;while((p=waitpid(-1,&st,WNOHANG))>0)kids.erase(remove(kids.begin(),kids.end(),p),kids.end());while(!stopflag&&(int)kids.size()<s.workers)spawn();}}for(int fd=0;fd<(int)listeners.size();fd++)close(listeners[fd].first);for(pid_t p:kids)kill(p,SIGTERM);for(pid_t p:kids)waitpid(p,nullptr,0);return 0;}
